CREATE TABLE writing_stale_reasons(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),section_id TEXT NOT NULL REFERENCES sections(id),cause_type TEXT NOT NULL,cause_id TEXT NOT NULL,cause_version TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,resolved_at TEXT,resolution_ref TEXT,UNIQUE(section_id,cause_type,cause_id,cause_version));
CREATE INDEX idx_writing_stale_section ON writing_stale_reasons(project_id,section_id,status);
CREATE INDEX idx_writing_dependencies_upstream ON object_dependencies(project_id,upstream_type,upstream_id);
CREATE TABLE writing_commit_receipts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,candidate_kind TEXT NOT NULL,candidate_id TEXT NOT NULL,result_blob TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,idempotency_key));
CREATE TABLE writing_joint_reviews(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),input_blob TEXT NOT NULL,input_hash TEXT NOT NULL,result_blob TEXT,status TEXT NOT NULL,task_id TEXT REFERENCES tasks(id),created_at TEXT NOT NULL);
CREATE TABLE diagnostic_reviews(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),item_id TEXT NOT NULL REFERENCES diagnostic_items(id),evaluator_id TEXT NOT NULL,method TEXT NOT NULL,blinded INTEGER NOT NULL,dimensions_json TEXT NOT NULL,decision TEXT NOT NULL,note TEXT NOT NULL,input_hash TEXT NOT NULL,created_at TEXT NOT NULL,duration_seconds REAL);
CREATE INDEX idx_diagnostic_reviews_item ON diagnostic_reviews(item_id,created_at);
CREATE TABLE diagnostic_adjudications(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),item_id TEXT NOT NULL REFERENCES diagnostic_items(id),review_ids_json TEXT NOT NULL,decision TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL,resolved_dimensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE diagnostic_comparisons(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),factor TEXT NOT NULL,policy_json TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE diagnostic_comparison_members(comparison_id TEXT NOT NULL REFERENCES diagnostic_comparisons(id),arm TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES diagnostic_runs(id),PRIMARY KEY(comparison_id,arm));
CREATE TABLE diagnostic_comparison_results(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),comparison_id TEXT NOT NULL REFERENCES diagnostic_comparisons(id),result_blob TEXT NOT NULL,method TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE writing_quality_policies(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),role TEXT NOT NULL,content_json TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TEXT NOT NULL);
